package ru.nartov.lab6.controller;
import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import ru.nartov.lab6.dto.*;import ru.nartov.lab6.entity.Student;import ru.nartov.lab6.service.StudentService;import java.util.List;
@RestController @RequestMapping("/api/students") public class StudentController{private final StudentService service;public StudentController(StudentService s){service=s;}@GetMapping public ResponseEntity<ApiResponse<List<Student>>> findAll(){return ResponseEntity.ok(ApiResponse.success("Список студентов получен.",service.findAll()));}@GetMapping("/{id}")public ResponseEntity<ApiResponse<Student>> findById(@PathVariable Long id){return ResponseEntity.ok(ApiResponse.success("Студент найден.",service.findById(id)));}@PostMapping public ResponseEntity<ApiResponse<Student>> create(@Valid @RequestBody StudentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Студент успешно создан.",service.create(r)));}@PutMapping("/{id}")public ResponseEntity<ApiResponse<Student>> update(@PathVariable Long id,@Valid @RequestBody StudentRequest r){return ResponseEntity.ok(ApiResponse.success("Студент успешно обновлён.",service.update(id,r)));}@DeleteMapping("/{id}")public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.ok(ApiResponse.success("Студент успешно удалён.",null));}}
